#include <stdio.h>
int triangular(int n){int s=0;for(int i=1;i<=n;i++)s+=i;return s;}
int main(void){int n;if(scanf("%d",&n)!=1)return 1;printf("triangular=%d\n",triangular(n));return 0;}

