#include <stdio.h>
void summarize(const int *a,int n,int t,int *sum,int *above){*sum=0;*above=0;for(const int *p=a;p<a+n;p++){*sum+=*p;if(*p>t)(*above)++;}}
int main(void){int n,a[20],t,s,c;if(scanf("%d",&n)!=1)return 1;for(int i=0;i<n;i++)if(scanf("%d",&a[i])!=1)return 1;if(scanf("%d",&t)!=1)return 1;summarize(a,n,t,&s,&c);printf("sum=%d above=%d\n",s,c);return 0;}

