#include <stdio.h>
typedef struct{int id,score;} Student;
int main(void){Student a[15];int n,best=0;if(scanf("%d",&n)!=1)return 1;for(int i=0;i<n;i++)if(scanf("%d %d",&a[i].id,&a[i].score)!=2)return 1;for(int i=1;i<n;i++)if(a[i].score>a[best].score)best=i;printf("top=%d\n",a[best].id);return 0;}

